class Solution:
    def maxIncreasingGroups(self, usageLimits: List[int]) -> int:
        # Sort in descending order to make it easier to reason about
        usageLimits.sort(reverse=True)

        def can_form_groups(k):
            if k == 0:
                return True

            # Total slots needed for k groups with sizes 1, 2, ..., k
            total_slots = k * (k + 1) // 2

            # Calculate minimum usage we can get from each number
            # Each number i can contribute at most min(usageLimits[i], k) to the total
            available_usage = 0
            for limit in usageLimits:
                available_usage += min(limit, k)

            return available_usage >= total_slots

        # Binary search for the maximum number of groups
        left, right = 0, len(usageLimits)
        result = 0

        while left <= right:
            mid = (left + right) // 2
            if can_form_groups(mid):
                result = mid
                left = mid + 1
            else:
                right = mid - 1

        return result

