from itertools import combinations

def solve():
    # Read input
    N, M = map(int, input().split())
    stands = []
    for _ in range(N):
        stands.append(input().strip())

    # Check if we can get all flavors from k stands, starting from k=1
    for k in range(1, N + 1):
        # Generate all combinations of k stands
        for stand_combo in combinations(range(N), k):
            # Check if this combination covers all flavors
            covered_flavors = set()
            for stand_idx in stand_combo:
                # Add all flavors sold by this stand
                for j in range(M):
                    if stands[stand_idx][j] == 'o':
                        covered_flavors.add(j)

            # Check if all M flavors are covered
            if len(covered_flavors) == M:
                return k

    return N  # This should never happen given the constraints

