from itertools import combinations

def solve():
    # Read input
    N, M = map(int, input().split())
    stands = []
    for _ in range(N):
        stands.append(input().strip())

    # Check if any single stand has all flavors
    for i in range(N):
        all_flavors = True
        for j in range(M):
            if stands[i][j] == 'x':
                all_flavors = False
                break
        if all_flavors:
            return 1

    # Check all pairs of stands
    for r in range(2, N + 1):
        for stand_combo in combinations(range(N), r):
            # Check if this combination covers all flavors
            covered = set()
            for stand_idx in stand_combo:
                for j in range(M):
                    if stands[stand_idx][j] == 'o':
                        covered.add(j)

            if len(covered) == M:
                return r

    # This should never happen given the problem constraints
    return N

print(solve())

